  FOR INSERT TO authenticated
  WITH CHECK (EXISTS (SELECT 1 FROM public.mw_care_teams t WHERE t.id = team_id
    AND (t.patient_id = auth.uid() OR public.is_active_coordinator(auth.uid()))));
